INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID001',N'Hà Giang · Đi giữa mùa mây','/assets/posters/1.svg',301,N'Một hành trình chậm qua những cung đường và thung lũng xanh nơi địa đầu Tổ quốc.',1,1);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID002',N'Đà Lạt · Những ngày thật chậm','/assets/posters/2.svg',474,N'Tìm một quán nhỏ, nhâm nhi cà phê và để sương mai kể câu chuyện của phố núi.',1,1);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID003',N'Ninh Bình · Miền di sản xanh','/assets/posters/3.svg',647,N'Đi thuyền qua núi đá vôi, ngắm những cánh đồng và khám phá vẻ đẹp của Tràng An.',1,1);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID004',N'Phú Yên · Chạm vào biển xanh','/assets/posters/4.svg',820,N'Theo bước chân đến những bãi biển yên bình và đón bình minh trên bờ cát.',1,1);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID005',N'Java Web · Bắt đầu từ nền tảng','/assets/posters/5.svg',993,N'Khám phá cách Servlet, JSP và JDBC cùng hoạt động trong một ứng dụng web.',1,2);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID006',N'Góc làm việc · Tối giản để tập trung','/assets/posters/6.svg',1166,N'Những thay đổi nhỏ giúp không gian làm việc gọn gàng và dễ tập trung hơn.',1,2);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID007',N'Thiết kế giao diện · Từ ý tưởng đến thực tế','/assets/posters/7.svg',1339,N'Tìm hiểu nhịp điệu, màu sắc và khoảng trắng trong một sản phẩm số.',1,2);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID008',N'Một ngày cùng công nghệ xanh','/assets/posters/8.svg',1512,N'Những ý tưởng công nghệ giúp chúng ta xây dựng thói quen sống bền vững.',1,2);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID009',N'Cà phê Việt · Một câu chuyện thơm','/assets/posters/9.svg',1685,N'Từ hạt cà phê đến tách phin buổi sáng, khám phá hương vị rất riêng của Việt Nam.',1,3);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID010',N'Bếp nhà · Bữa cơm mùa hạ','/assets/posters/10.svg',1858,N'Những nguyên liệu thân quen mang đến bữa cơm giản dị và ấm áp bên gia đình.',1,3);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID011',N'Sài Gòn · Hương vị trong con hẻm','/assets/posters/11.svg',2031,N'Dạo một vòng phố nhỏ và tìm những món ngon kể chuyện về thành phố.',1,3);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID012',N'Làm bánh · Niềm vui từ điều nhỏ','/assets/posters/12.svg',2204,N'Một buổi cuối tuần thơm mùi bánh mới và những khoảnh khắc tự tay sáng tạo.',1,3);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID013',N'Sống chậm · Một buổi sáng bình yên','/assets/posters/13.svg',2377,N'Dành một khoảng nhỏ trong ngày để hít thở, đọc sách và lắng nghe bản thân.',1,4);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID014',N'Không gian xanh · Mang thiên nhiên về nhà','/assets/posters/14.svg',2550,N'Gợi ý bố trí cây xanh để mỗi góc nhà trở nên nhẹ nhàng và tươi mới.',1,4);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID015',N'Đọc sách · Mở thêm một thế giới','/assets/posters/15.svg',2723,N'Những trang sách và thói quen đọc giúp mỗi ngày có thêm một góc nhìn.',1,4);
INSERT INTO Videos(VideoId,Title,Poster,Views,Description,Active,CategoryId) VALUES('VID016',N'Đi bộ · Tìm lại nhịp điệu của mình','/assets/posters/16.svg',2896,N'Bước ra ngoài, cảm nhận không khí trong lành và nhìn thành phố theo cách khác.',1,4);
